const normalizeItems = (items: any[]) => {
  const map = new Map<string, any>();
  items.forEach((item: any) => {
    const key = (item.nome_produto || "").toLowerCase().trim();
    if (!key) return;
    if (map.has(key)) {
      const existing = map.get(key);
      existing.quantidade += item.quantidade || 0;
      existing.subtotal += item.subtotal || 0;
    } else { map.set(key, { ...item }); }
  });
  return Array.from(map.values());
};

const handleFileSelected = (file: File | null) => { setUploadFile(file); setUploadFiles(file ? [file] : []); };
const handleFilesSelected = (files: File[]) => { setUploadFiles(files); setUploadFile(files[0] || null); };

const runOcr = async () => {
  if (uploadFiles.length === 0 || processingRef.current) return;
  processingRef.current = true;
  setIsProcessingOcr(true);
  try {
    const allImagesBase64: string[] = [];
    for (const file of uploadFiles) {
      if (file.type === "application/pdf") {
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await getDocument({ data: arrayBuffer }).promise;
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const viewport = page.getViewport({ scale: 2 });
          const canvas = document.createElement("canvas");
          canvas.width = viewport.width; canvas.height = viewport.height;
          const ctx = canvas.getContext("2d")!;
