toolUseResult.originalFile:
// Helper de redimensionamento + recompressão de imagem.
//
// PORQUÊ: fotos de câmera mobile e páginas de PDF chegam em altíssima resolução
// e, quando convertidas direto em base64, mantêm várias cópias enormes vivas em
// memória ao mesmo tempo (data URL crua + base64 + payload da edge function).
// Em abas mobile isso estoura o navegador antes mesmo de chamar o OCR. Reduzir o
// lado maior para 2000px e recomprimir em JPEG 0.85 corta o pico de memória em
// ~1 ordem de grandeza sem perda relevante de leitura do OCR.

/** Lado maior máximo (px) aprovado para conversões de imagem do OCR de NF. */
export const NF_IMAGE_MAX_DIM = 2000;

/** Qualidade JPEG aprovada para conversões de imagem do OCR de NF. */
export const NF_IMAGE_JPEG_QUALITY = 0.85;

/** Remove o prefixo `data:image/...;base64,` retornando só o payload base64. */
export function stripDataUrlPrefix(dataUrl: string): string {
  const commaIdx = dataUrl.indexOf(',');
  return commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl;
}

/**
 * Calcula a escala de downscale mantendo proporção.
 * PORQUÊ: nunca fazer upscale — se a imagem já é menor que maxDim, escala = 1
 * para não inflar memória/peso sem ganho de leitura.
 */
function computeScale(width: number, height: number, maxDim: number): number {
  const largest = Math.max(width, height);
  return largest > maxDim ? maxDim / largest : 1;
}

interface Dimensions {
  width: number;
  height: number;
}

/**
 * Desenha a fonte (ImageBitmap ou HTMLImageElement) num canvas com lado maior
 * limitado a maxDim e exporta JPEG. Libera o canvas no finally porque um canvas
 * grande não liberado é justamente uma das cópias que estouram a memória.
 */
function drawToJpegBase64(
  source: CanvasImageSource,
  dims: Dimensions,
  maxDim: number,
  quality: number,
): string {
  const scale = computeScale(dims.width, dims.height, maxDim);
  const canvas = document.createElement('canvas');
  try {
    canvas.width = Math.round(dims.width * scale);
    canvas.height = Math.round(dims.height * scale);
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Canvas 2D context indisponível');
    }
    ctx.drawImage(source, 0, 0, canvas.width, canvas.height);
    const dataUrl = canvas.toDataURL('image/jpeg', quality);
    return stripDataUrlPrefix(dataUrl);
  } finally {
    // Zera o canvas para que o backing store seja coletado imediatamente.
    canvas.width = 0;
    canvas.height = 0;
  }
}

/** Caminho de fallback via HTMLImageElement quando createImageBitmap falha. */
function blobToBase64ViaImage(
  blob: Blob,
  maxDim: number,
  quality: number,
): Promise<string> {
  return new Promise<string>((resolve, reject) => {
    const url = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => {
      try {
        const base64 = drawToJpegBase64(
          img,
          { width: img.naturalWidth, height: img.naturalHeight },
          maxDim,
          quality,
        );
        resolve(base64);
      } catch (err) {
        reject(err instanceof Error ? err : new Error(String(err)));
      } finally {
        // Libera o object URL para não vazar o blob original em memória.
        URL.revokeObjectURL(url);
      }
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Falha ao carregar imagem para downscale'));
    };
    img.src = url;
  });
}

/**
 * Converte um Blob/File de imagem para base64 JPEG já reduzido.
 * Usa createImageBitmap quando disponível (mais leve, sem manter HTMLImageElement
 * vivo) e cai para Image+ObjectURL como fallback. Em ambos os caminhos os
 * recursos intermediários são liberados — esse é o ponto central do fix de
 * memória.
 */
export async function blobToDownscaledBase64(
  blob: Blob,
  maxDim: number = NF_IMAGE_MAX_DIM,
  quality: number = NF_IMAGE_JPEG_QUALITY,
): Promise<string> {
  if (typeof createImageBitmap === 'function') {
    let bitmap: ImageBitmap | null = null;
    try {
      bitmap = await createImageBitmap(blob);
      return drawToJpegBase64(
        bitmap,
        { width: bitmap.width, height: bitmap.height },
        maxDim,
        quality,
      );
    } catch {
      // Fallback silencioso: alguns navegadores/jsdom não suportam o formato.
      return blobToBase64ViaImage(blob, maxDim, quality);
    } finally {
      // close() devolve a memória do bitmap imediatamente.
      bitmap?.close();
    }
  }
  return blobToBase64ViaImage(blob, maxDim, quality);
}

/**
 * Lê um File de imagem e retorna SÓ o base64 JPEG já reduzido (sem prefixo
 * data URL). Assinatura principal usada pelo fluxo de OCR de NF.
 */
export async function fileToDownscaledBase64(
  file: File,
  maxDim: number = NF_IMAGE_MAX_DIM,
  quality: number = NF_IMAGE_JPEG_QUALITY,
): Promise<string> {
  return blobToDownscaledBase64(file, maxDim, quality);
}

/**
 * Lê um File de imagem e devolve um NOVO File JPEG já reduzido.
 *
 * PORQUÊ: o fluxo de captura por câmera na PWA mobile precisa de um File pra
 * trafegar pelos states (selectedFile/selectedFiles), upload pro Supabase
 * Storage e persistência durável (localStorage). Antes a captura mantinha o
 * File full-res em memória e ainda gerava um data URL gigante via
 * FileReader.readAsDataURL antes de reduzir — esse pico era a causa do OOM
 * que matava o WebView no Android. Aqui vamos direto do Blob ao File reduzido,
 * sem nenhum intermediário em resolução cheia.
 *
 * Saída sempre `image/jpeg` (forçamos a extensão `.jpg` no nome) porque o
 * downscale recomprime em JPEG.
 */
export async function fileToDownscaledFile(
  file: File,
  name?: string,
  maxDim: number = NF_IMAGE_MAX_DIM,
  quality: number = NF_IMAGE_JPEG_QUALITY,
): Promise<File> {
  const base64 = await blobToDownscaledBase64(file, maxDim, quality);
  // Decodifica o base64 já reduzido para bytes — peak de memória aqui é só o
  // tamanho do JPEG comprimido (~centenas de KB), não a foto crua.
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  const baseName = (name ?? file.name).replace(/\.[^.]+$/, '');
  const outName = `${baseName || 'foto'}.jpg`;
  return new File([bytes], outName, {
    type: 'image/jpeg',
    lastModified: Date.now(),
  });
}

/** Converte uma data URL em Blob sem manter a string crua além do necessário. */
function dataUrlToBlob(dataUrl: string): Blob {
  const [header, payload] = dataUrl.split(',');
  const mime = header.match(/:(.*?);/)?.[1] ?? 'image/jpeg';
  const binary = atob(payload);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new Blob([bytes], { type: mime });
}

