// Persistência durável da foto capturada em Notas Fiscais para sobreviver ao
// kill do WebView pelo Android (PWA via Vercel).
//
// PORQUÊ não sessionStorage: o WebView é morto pelo Android quando a câmera
// nativa fica em foreground; ao retornar, o processo é recriado e
// `sessionStorage` é apagado (é per-session). `localStorage` é persistido em
// disco pelo WebView e sobrevive ao kill.
//
// PORQUÊ não IndexedDB: o JPEG já reduzido (lado <=2000px, qualidade 0.85) cabe
// em ~200KB–1.1MB em base64, folgado dentro da quota típica de 5MB do
// localStorage. Não vale o custo de polyfill em testes nem a complexidade
// async pra um caso de uma foto por sessão.

const KEY_PHOTO = 'nf-pending-capture-v1';
const KEY_FLAG = 'nf-pending-capture-flag-v1';

/** TTL da captura pendente. Após 10 min é considerada irrecuperável. */
const PHOTO_TTL_MS = 10 * 60 * 1000;
/** TTL do flag "abri a câmera mas não voltei ainda" — curto e só serve pra
 * reabrir o modal de upload caso o usuário tenha cancelado a câmera. */
const FLAG_TTL_MS = 60 * 1000;

interface StoredPhoto {
  dataUrl: string;
  name: string;
  mime: string;
  ts: number;
}

/**
 * Acesso defensivo ao localStorage — alguns contextos (modo privado raro,
 * iframes sandboxed) podem lançar SecurityError no simples acesso ao objeto.
 */
function getStorage(): Storage | null {
  try {
    if (typeof window === 'undefined') return null;
    return window.localStorage;
  } catch {
    return null;
  }
}

function readJson<T>(key: string): T | null {
  const storage = getStorage();
  if (!storage) return null;
  try {
    const raw = storage.getItem(key);
    if (!raw) return null;
    return JSON.parse(raw) as T;
  } catch {
    // JSON corrompido — apaga pra não envenenar futuras leituras.
    try {
      storage.removeItem(key);
    } catch {
      /* noop */
    }
    return null;
  }
}

function dataUrlToFile(dataUrl: string, name: string, mime: string): File | null {
  try {
    const commaIdx = dataUrl.indexOf(',');
    if (commaIdx < 0) return null;
    const payload = dataUrl.slice(commaIdx + 1);
    const binary = atob(payload);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return new File([bytes], name, { type: mime || 'image/jpeg' });
  } catch {
    return null;
  }
}

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(reader.error ?? new Error('FileReader falhou'));
    reader.readAsDataURL(file);
  });
}

/**
 * Persiste a foto reduzida + metadados em localStorage com timestamp.
 *
 * Erros (quota excedida, FileReader, indisponibilidade do storage) são
 * silenciados porque essa persistência é defesa em profundidade — o fluxo
 * principal já tem o File em memória; só não há recuperação se o WebView
 * morrer.
 */
export async function savePendingCapture(file: File): Promise<void> {
  const storage = getStorage();
  if (!storage) return;
  try {
    const dataUrl = await fileToDataUrl(file);
    const payload: StoredPhoto = {
      dataUrl,
      name: file.name || 'foto.jpg',
      mime: file.type || 'image/jpeg',
      ts: Date.now(),
    };
    storage.setItem(KEY_PHOTO, JSON.stringify(payload));
  } catch {
    // QuotaExceededError ou afins — limpa nossa chave pra liberar espaço
    // pra próxima tentativa e segue silencioso.
    try {
      storage.removeItem(KEY_PHOTO);
    } catch {
      /* noop */
    }
  }
}

/** Marca que iniciamos uma captura (antes do click no input nativo). */
export function setPendingCaptureFlag(): void {
  const storage = getStorage();
  if (!storage) return;
  try {
    storage.setItem(KEY_FLAG, String(Date.now()));
  } catch {
    /* noop */
  }
}

/** Apaga só o flag de captura iniciada. */
export function clearPendingCaptureFlag(): void {
  const storage = getStorage();
  if (!storage) return;
  try {
    storage.removeItem(KEY_FLAG);
  } catch {
    /* noop */
  }
}

/**
 * Lê a captura pendente. Retorna `null` quando:
 * - não há nada armazenado;
 * - o TTL expirou (maior que 10 min) — nesse caso a entrada é apagada;
 * - o payload está corrompido ou o storage não está disponível.
 */
export function loadPendingCapture(): { file: File; ts: number } | null {
  const storage = getStorage();
  if (!storage) return null;
  const stored = readJson<StoredPhoto>(KEY_PHOTO);
  if (!stored || !stored.dataUrl || !stored.ts) return null;
  if (Date.now() - stored.ts > PHOTO_TTL_MS) {
    try {
      storage.removeItem(KEY_PHOTO);
    } catch {
      /* noop */
    }
    return null;
  }
  const file = dataUrlToFile(stored.dataUrl, stored.name, stored.mime);
  if (!file) return null;
  return { file, ts: stored.ts };
}

/** Remove a captura pendente e qualquer flag em uso. */
export function clearPendingCapture(): void {
  const storage = getStorage();
  if (!storage) return;
  try {
    storage.removeItem(KEY_PHOTO);
    storage.removeItem(KEY_FLAG);
  } catch {
    /* noop */
  }
}

/**
 * Resposta rápida pro hook de boot: existe captura pendente recente OU flag
 * recente "abri a câmera"? Usado pra decidir se redireciona o usuário pra
 * `/notas-fiscais` quando o app boota após um kill do WebView.
 */
export function hasRecentPendingCapture(): boolean {
  const storage = getStorage();
  if (!storage) return false;
  const now = Date.now();

  const stored = readJson<StoredPhoto>(KEY_PHOTO);
  if (stored?.ts && now - stored.ts <= PHOTO_TTL_MS) return true;

  try {
    const flagRaw = storage.getItem(KEY_FLAG);
    if (flagRaw) {
      const flagTs = Number(flagRaw);
      if (Number.isFinite(flagTs) && now - flagTs <= FLAG_TTL_MS) return true;
    }
  } catch {
    /* noop */
  }
  return false;
}

// Re-export das constantes pra facilitar testes e ajuste futuro.
export const NF_PENDING_CAPTURE_KEYS = { KEY_PHOTO, KEY_FLAG };
export const NF_PENDING_CAPTURE_TTLS = { PHOTO_TTL_MS, FLAG_TTL_MS };

