import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  stripDataUrlPrefix,
  fileToDownscaledBase64,
  fileToDownscaledFile,
  NF_IMAGE_MAX_DIM,
  NF_IMAGE_JPEG_QUALITY,
} from './downscaleImage';

// PORQUÊ destes mocks: jsdom não implementa canvas nem createImageBitmap.
// Mockamos o mínimo para validar a lógica de dimensionamento (não-upscale,
// limite de maxDim) e o contrato de retorno (base64 sem prefixo), sem depender
// de um motor de imagem real.

interface FakeCtx {
  drawImage: ReturnType<typeof vi.fn>;
}

let lastCanvas: { width: number; height: number } | null = null;

beforeEach(() => {
  lastCanvas = null;

  vi.spyOn(document, 'createElement').mockImplementation((tag: string) => {
    if (tag === 'canvas') {
      const ctx: FakeCtx = { drawImage: vi.fn() };
      const canvas = {
        width: 0,
        height: 0,
        getContext: () => ctx,
        // Devolve uma data URL determinística que codifica as dimensões
        // exportadas, permitindo asserções sobre o downscale aplicado.
        toDataURL: vi.fn(function (this: { width: number; height: number }) {
          lastCanvas = { width: this.width, height: this.height };
          return 'data:image/jpeg;base64,QUJD';
        }),
      };
      return canvas as unknown as HTMLCanvasElement;
    }
    return {} as HTMLElement;
  });
});

afterEach(() => {
  vi.restoreAllMocks();
});

function mockBitmap(width: number, height: number) {
  const close = vi.fn();
  vi.stubGlobal(
    'createImageBitmap',
    vi.fn(async () => ({ width, height, close }) as unknown as ImageBitmap),
  );
  return { close };
}

describe('stripDataUrlPrefix', () => {
  it('remove o prefixo data URL retornando só o base64', () => {
    expect(stripDataUrlPrefix('data:image/jpeg;base64,QUJD')).toBe('QUJD');
  });

  it('retorna a string intacta quando não há prefixo', () => {
    expect(stripDataUrlPrefix('QUJD')).toBe('QUJD');
  });
});

describe('fileToDownscaledBase64', () => {
  it('retorna base64 sem o prefixo data:image', async () => {
    mockBitmap(100, 100);
    const file = new File([new Uint8Array([1, 2, 3])], 'foto.jpg', { type: 'image/jpeg' });
    const result = await fileToDownscaledBase64(file);
    expect(result).toBe('QUJD');
    expect(result.startsWith('data:')).toBe(false);
  });

  it('NÃO faz upscale de imagem menor que maxDim (mantém tamanho original)', async () => {
    const { close } = mockBitmap(800, 600);
    const file = new File([new Uint8Array([1])], 'pequena.jpg', { type: 'image/jpeg' });
    await fileToDownscaledBase64(file);
    expect(lastCanvas).toEqual({ width: 800, height: 600 });
    expect(close).toHaveBeenCalled();
  });

  it('reduz o lado maior para maxDim mantendo proporção', async () => {
    mockBitmap(4000, 2000);
    const file = new File([new Uint8Array([1])], 'grande.jpg', { type: 'image/jpeg' });
    await fileToDownscaledBase64(file);
    // lado maior 4000 -> 2000 (escala 0.5); 2000 -> 1000
    expect(lastCanvas).toEqual({ width: NF_IMAGE_MAX_DIM, height: 1000 });
  });

  it('expõe os parâmetros de qualidade aprovados', () => {
    expect(NF_IMAGE_MAX_DIM).toBe(2000);
    expect(NF_IMAGE_JPEG_QUALITY).toBe(0.85);
  });
});

describe('fileToDownscaledFile', () => {
  it('devolve um File JPEG já reduzido (sem data URL intermediária)', async () => {
    mockBitmap(4000, 3000);
    // Conteúdo cru "grande" — o helper não pode preservar esse tamanho.
    const heavy = new Uint8Array(50_000).fill(7);
    const file = new File([heavy], 'foto.png', { type: 'image/png' });

    const out = await fileToDownscaledFile(file);

    expect(out).toBeInstanceOf(File);
    expect(out.type).toBe('image/jpeg');
    // canvas mockado emite `QUJD` (base64 de "ABC") → 3 bytes na saída.
    expect(out.size).toBe(3);
    expect(out.size).toBeLessThan(file.size);
  });

  it('força a extensão .jpg mesmo quando o arquivo original era PNG/HEIC', async () => {
    mockBitmap(800, 600);
    const file = new File([new Uint8Array([1])], 'IMG_1234.heic', { type: 'image/heic' });
    const out = await fileToDownscaledFile(file);
    expect(out.name).toBe('IMG_1234.jpg');
  });

  it('respeita o nome customizado quando fornecido', async () => {
    mockBitmap(800, 600);
    const file = new File([new Uint8Array([1])], 'qualquer.jpg', { type: 'image/jpeg' });
    const out = await fileToDownscaledFile(file, 'nota-fiscal');
    expect(out.name).toBe('nota-fiscal.jpg');
  });

  it('usa fallback de nome quando File e custom name estão vazios', async () => {
    mockBitmap(800, 600);
    // Nome vazio é válido (File API aceita), e simula casos exóticos do mobile.
    const file = new File([new Uint8Array([1])], '', { type: 'image/jpeg' });
    const out = await fileToDownscaledFile(file);
    expect(out.name).toBe('foto.jpg');
  });
});

