describe('fileToOcrBase64', () => {
  it('lê lossless (sem recomprimir) quando o arquivo está abaixo do teto', async () => {
    // Bytes 1,2,3 -> base64 "AQID". Se recomprimisse, passaria pelo canvas mockado
    // ("QUJD") — então assertar "AQID" prova que NÃO houve segunda compressão.
    const file = new File([new Uint8Array([1, 2, 3])], 'foto.jpg', { type: 'image/jpeg' });
    const result = await fileToOcrBase64(file);
    expect(result).toBe('AQID');
    // Não tocou no canvas: o caminho lossless não desenha nada.
    expect(lastCanvas).toBeNull();
  });

  it('cai no downscale como salvaguarda quando o arquivo excede o teto', async () => {
    mockBitmap(800, 600);
    const heavy = new Uint8Array(NF_OCR_LOSSLESS_MAX_BYTES + 1).fill(7);
    const file = new File([heavy], 'gigante.jpg', { type: 'image/jpeg' });
    const result = await fileToOcrBase64(file);
    // Passou pelo canvas mockado -> recomprimiu.
    expect(result).toBe('QUJD');
    expect(lastCanvas).toEqual({ width: 800, height: 600 });
  });
});

