import { useState, useRef, DragEvent, ChangeEvent, useEffect } from "react";
import { Upload, FileText, CheckCircle, Camera, Plus, X } from "lucide-react";
import { Input } from "@/shared/ui/input";
import { Button } from "@/shared/ui/button";
import { cn } from "@/shared/lib/utils";
import { useIsMobile } from "@/shared/hooks/use-mobile";
import { useHasCamera } from "@/shared/hooks/use-mobile";
import { toast } from "sonner";
import { wideError } from '@/shared/lib/telemetry/wide-events';
import { fileToDownscaledFile } from "@/features/notas-fiscais/lib/downscaleImage";
import {
  savePendingCapture,
  setPendingCaptureFlag,
  clearPendingCaptureFlag,
} from "@/features/notas-fiscais/lib/pendingCapture";

interface DragDropUploadAreaProps {
  onFileSelect: (file: File) => void;
  selectedFile: File | null;
  onFilesSelect?: (files: File[]) => void;
  selectedFiles?: File[];
  multiple?: boolean;
  accept?: string;
  disabled?: boolean;
}

/**
 * Garante que imagens sejam reduzidas (≤2000px, JPEG 0.85) antes de entrar no
 * state da página. PDFs passam intactos — pdf.js cuida do downscale por página
 * no `processImage`/`pdfToImageBase64Pages`.
 *
 * PORQUÊ: a foto crua de câmera mobile (≈4000×3000, ~10MB de dataURL ao
 * decodificar) é o pico que matava o WebView Android. Reduzir na ORIGEM —
 * antes do File entrar em selectedFile/selectedFiles — limita o pico a
 * centenas de KB e elimina cópias gigantes em memória.
 */
async function downscaleIfImage(file: File): Promise<File> {
  if (!file.type.startsWith('image/')) return file;
  try {
    return await fileToDownscaledFile(file);
  } catch (error) {
    wideError('dragDropUpload.downscaleImagem', 'Erro ao reduzir imagem; mantendo arquivo original como fallback', {
      attributes: {
        'error.message': String((error as Error)?.message || error),
        'operation.name': 'downscaleAtSource',
        'file.name': file.name,
        'file.type': file.type,
        'file.size': file.size,
      },
    });
    return file;
  }
}

export const DragDropUploadArea = ({
  onFileSelect,
  selectedFile,
  onFilesSelect,
  selectedFiles = [],
  multiple = false,
  accept = 'image/*',
  disabled = false,
}: DragDropUploadAreaProps) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const [isHovering, setIsHovering] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  // Guarda anti-double-click; o flag durável (localStorage) é setado em paralelo
  // por setPendingCaptureFlag e serve ao hook de boot que redireciona pra NF.
  const isCapturing = useRef(false);

  // Limpa o flag durável quando o usuário volta pro WebView (focus) — cobre o
  // caso de o usuário ter aberto a câmera e cancelado sem tirar foto. O flag
  // tem TTL próprio, isso é só a faxina best-effort no caminho feliz.
  useEffect(() => {
    const onFocus = () => {
      if (isCapturing.current) {
        // Pequeno delay: em alguns devices o onchange do input chega DEPOIS
        // do focus; se a foto vier, savePendingCapture cuida do flag.
        setTimeout(() => {
          if (isCapturing.current) {
            clearPendingCaptureFlag();
            isCapturing.current = false;
          }
        }, 1500);
      }
    };
    window.addEventListener('focus', onFocus);
    return () => window.removeEventListener('focus', onFocus);
  }, []);

  const handleDragEnter = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (!disabled) {
      setIsDragOver(true);
    }
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();

    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX;
    const y = e.clientY;

    if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) {
      setIsDragOver(false);
    }
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = async (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);

    if (disabled) return;

    const files = Array.from(e.dataTransfer.files);
    if (files.length === 0) return;
    const validFiles = files.filter(f => {
      if (accept === 'image/*') return f.type.startsWith('image/');
      return accept.split(',').some(a => {
        const pat = '^' + a.trim().replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace('\\*', '.*') + '$';
        return new RegExp(pat).test(f.type);
      });
    });
    if (validFiles.length === 0) return;

    // Downscale de imagens na entrada — vale tanto pro mobile (galeria) quanto
    // pra desktop (drag/drop): mantém o pipeline de memória previsível.
    const processed = await Promise.all(validFiles.map(downscaleIfImage));

    if (multiple && onFilesSelect) {
      const merged = [...selectedFiles, ...processed].slice(0, 2);
      onFilesSelect(merged);
    } else {
      onFileSelect(processed[0]);
    }
  };

  const handleFileInputChange = async (e: ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) {
      e.target.value = '';
      return;
    }
    const inputFiles = Array.from(files);
    const processed = await Promise.all(inputFiles.map(downscaleIfImage));
    if (multiple && onFilesSelect) {
      const merged = [...selectedFiles, ...processed].slice(0, 2);
      onFilesSelect(merged);
    } else {
      onFileSelect(processed[0]);
    }
    // Reset value para permitir re-seleção do mesmo arquivo
    e.target.value = '';
  };

  const isMobile = useIsMobile();
  const { hasCamera, isChecking } = useHasCamera();

  const handleClick = () => {
    if (disabled) return;
    if (isCapturing.current) return;
    // Se já tem 2 arquivos no multi-mode, não abrir seleção (limite atingido)
    if (multiple && selectedFiles.length >= 2) return;
    if (isMobile && hasCamera) {
      setPendingCaptureFlag();
      isCapturing.current = true;
      cameraInputRef.current?.click();
      return;
    }
    fileInputRef.current?.click();
  };

  const handleCameraClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!disabled && hasCamera && !isCapturing.current) {
      setPendingCaptureFlag();
      isCapturing.current = true;
      cameraInputRef.current?.click();
    }
  };

  const handleCameraCapture = async (e: ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    const raw = files && files.length > 0 ? files[0] : null;
    // Sempre limpa o flag — recebemos retorno do input (com ou sem foto).
    clearPendingCaptureFlag();
    isCapturing.current = false;
    if (!raw) {
      e.target.value = '';
      return;
    }

    // PORQUÊ downscale ANTES de entregar via onFileSelect: o File cru de câmera
    // de Android costuma ter 5-10MB e segura um pico de ~13MB de dataURL ao
    // decodificar. Esse pico era o gatilho do OOM que matava o WebView.
    // O File reduzido (lado ≤2000px, JPEG 0.85) cabe em ~200KB–1MB e
    // remove a foto crua do alcance do GC sem cópias intermediárias.
    const downscaled = await downscaleIfImage(raw);

    if (multiple && onFilesSelect) {
      // Multi-mode não persiste em localStorage (restore não suporta multi).
      const merged = [...selectedFiles, downscaled].slice(0, 2);
      onFilesSelect(merged);
      toast.success(`Foto ${merged.length} capturada com sucesso!`);
    } else {
      onFileSelect(downscaled);
      toast.success("Foto capturada com sucesso!");
      // Defesa em profundidade: persiste a foto reduzida em localStorage pra
      // permitir restore caso o Android mate o WebView antes do upload.
      // Falha aqui é silenciosa por design (a foto já está em memória).
      void savePendingCapture(downscaled);
    }

    e.target.value = '';
  };

  return (
    <div
      className={cn(
        'relative border-2 border-dashed rounded-lg p-4 sm:p-8 text-center transition-all duration-300 cursor-pointer',
        'hover:border-primary/50 hover:bg-primary/5',
        {
          'border-primary bg-primary/10 shadow-lg scale-[1.02]': isDragOver,
          'border-company-light': !isDragOver && !selectedFile && selectedFiles.length === 0,
          'border-green-400 bg-green-50': (selectedFile || selectedFiles.length > 0) && !isDragOver,
          'opacity-50 cursor-not-allowed': disabled,
          'transform hover:scale-[1.01]': !disabled && isHovering,
        },
      )}
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
      onClick={handleClick}
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => setIsHovering(false)}
    >
      {/* Efeito de brilho quando em drag over */}
      {isDragOver && (
        <div
          className="absolute inset-0 bg-gradient-to-r from-blue-400/20 via-purple-400/20 to-blue-400/20 rounded-lg"
          style={{ animation: 'pulse 3s ease-in-out infinite' }}
        />
      )}

      {/* Círculos animados quando em drag over */}
      {isDragOver && (
        <>
          <div
            className="absolute top-4 left-4 w-3 h-3 bg-primary/40 rounded-full"
            style={{
              animation: 'bounce 2s ease-in-out infinite',
              animationDelay: '0s',
            }}
          />
          <div
            className="absolute top-4 right-4 w-3 h-3 bg-primary/40 rounded-full"
            style={{
              animation: 'bounce 2s ease-in-out infinite',
              animationDelay: '0.5s',
            }}
          />
          <div
            className="absolute bottom-4 left-4 w-3 h-3 bg-primary/40 rounded-full"
            style={{
              animation: 'bounce 2s ease-in-out infinite',
              animationDelay: '1s',
            }}
          />
          <div
            className="absolute bottom-4 right-4 w-3 h-3 bg-primary/40 rounded-full"
            style={{
              animation: 'bounce 2s ease-in-out infinite',
              animationDelay: '1.5s',
            }}
          />
        </>
      )}

      <div className="relative z-10">
        {/* Multi-file mode: show list of selected files */}
        {multiple && selectedFiles.length > 0 ? (
          <div className="space-y-3 sm:space-y-4">
            <div className="flex items-center justify-center">
              <div className="w-12 h-12 sm:w-16 sm:h-16 bg-green-100 rounded-full flex items-center justify-center">
                <CheckCircle className="w-6 h-6 sm:w-8 sm:h-8 text-green-600" />
              </div>
            </div>
            <div className="space-y-2">
              <p className="text-base sm:text-lg font-semibold text-green-700">
                {selectedFiles.length === 1 ? '1 página selecionada' : `${selectedFiles.length} páginas selecionadas`}
              </p>
              {selectedFiles.map((f, idx) => (
                <div key={idx} className="flex items-center justify-center gap-2 text-sm text-green-600">
                  <FileText className="h-3.5 w-3.5 flex-shrink-0" />
                  <span className="font-medium truncate max-w-[200px]">Pág. {idx + 1}: {f.name}</span>
                  <span className="text-xs text-muted-foreground">({(f.size / 1024 / 1024).toFixed(2)} MB)</span>
                  <button
                    type="button"
                    className="p-0.5 rounded-full hover:bg-red-100 text-red-400 hover:text-red-600 transition-colors"
                    onClick={(e) => {
                      e.stopPropagation();
                      const updated = selectedFiles.filter((_, i) => i !== idx);
                      onFilesSelect?.(updated);
                    }}
                  >
                    <X className="h-3.5 w-3.5" />
                  </button>
                </div>
              ))}
              {selectedFiles.length < 2 && (
                <div className="pt-2 flex items-center justify-center gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      fileInputRef.current?.click();
                    }}
                    disabled={disabled}
                    className="gap-2 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/10 font-medium h-9 px-3 text-sm rounded-full"
                  >
                    <Plus className="h-4 w-4" />
                    Adicionar 2ª página
                  </Button>
                  {isMobile && hasCamera && !isChecking && (
                    <Button data-mia-action="camera-click"
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={handleCameraClick}
                      disabled={disabled}
                      className="gap-2 bg-primary/10 border-primary/30 hover:bg-primary/20 text-primary font-medium h-9 px-3 text-sm rounded-full"
                    >
                      <Camera className="h-4 w-4" />
                      Tirar 2ª foto
                    </Button>
                  )}
                </div>
              )}
            </div>
          </div>
        ) : selectedFile ? (
          <div className="space-y-3 sm:space-y-4">
            <div className="flex items-center justify-center">
              <div className="w-12 h-12 sm:w-16 sm:h-16 bg-green-100 rounded-full flex items-center justify-center">
                <CheckCircle className="w-6 h-6 sm:w-8 sm:h-8 text-green-600" />
              </div>
            </div>
            <div>
              <p className="text-base sm:text-lg font-semibold text-green-700 mb-2">
                Arquivo selecionado com sucesso!
              </p>
              <p className="text-sm text-green-600 font-medium truncate px-2">
                {selectedFile.name}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
              </p>
            </div>
          </div>
        ) : (
          <div className="space-y-3 sm:space-y-4">
            <div className="flex items-center justify-center">
              <div
                className={cn(
                  'w-12 h-12 sm:w-16 sm:h-16 rounded-full flex items-center justify-center transition-all duration-300',
                  {
                    'bg-primary/20 scale-110': isDragOver,
                    'bg-company-light/20': !isDragOver,
                  },
                )}
              >
                {isDragOver ? (
                  <FileText
                    className={cn(
                      'w-6 h-6 sm:w-8 sm:h-8 transition-all duration-300',
                      'text-primary',
                    )}
                    style={{ animation: 'pulse 2.5s ease-in-out infinite' }}
                  />
                ) : (
                  <Upload className="w-6 h-6 sm:w-8 sm:h-8 text-company-medium" />
                )}
              </div>
            </div>

            <div>
              {isDragOver ? (
                <div className="space-y-2">
                  <p
                    className="text-base sm:text-lg font-semibold text-primary"
                    style={{ animation: 'pulse 2.5s ease-in-out infinite' }}
                  >
                    Solte o arquivo aqui!
                  </p>
                  <p className="text-sm text-primary/80 px-2">
                    Estamos prontos para receber sua nota fiscal
                  </p>
                </div>
              ) : (
                <div className="space-y-2 sm:space-y-3">
                  <p className="text-base sm:text-lg font-semibold text-foreground px-2">
                    Arraste sua nota fiscal aqui
                  </p>
                  <p className="text-sm text-muted-foreground px-2">
                    ou clique para selecionar um arquivo
                    {isMobile && hasCamera && ' ou use o botão de câmera'}
                  </p>
                  <p className="text-xs text-muted-foreground px-2">
                    Suporta imagens JPG, PNG, PDF
                  </p>

                  {/* Botão de câmera para mobile */}
                  {isMobile && hasCamera && !isChecking && (
                    <div className="pt-2">
                      <Button data-mia-action="camera-click"
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={handleCameraClick}
                        disabled={disabled}
                        className="gap-2 bg-primary/10 border-primary/30 hover:bg-primary/20 text-primary font-medium h-10 px-4 text-sm"
                      >
                        <Camera className="h-4 w-4 flex-shrink-0" />
                        <span className="truncate">Tirar Foto</span>
                      </Button>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      <Input
        ref={fileInputRef}
        type="file"
        accept={accept}
        onChange={handleFileInputChange}
        className="hidden"
        disabled={disabled}
      />

      {/* Input oculto para captura de câmera */}
      <input
        ref={cameraInputRef}
        type="file"
        accept="image/*,image/jpeg,image/jpg,image/png"
        capture="environment"
        onChange={handleCameraCapture}
        style={{ display: 'none' }}
        disabled={disabled}
        // Atributos específicos para melhor compatibilidade mobile
        autoComplete="off"
        tabIndex={-1}
        multiple={false}
        // Força o uso da câmera traseira em dispositivos móveis
        data-camera="environment"
      />
    </div>
  );
};

