// O pico de memória que matava o WebView do Android vinha da DECODIFICAÇÃO da
// foto crua (~12MP da câmera → dezenas de MB de bitmap + ~13MB de data URL), NÃO
// do peso do output. Por isso reduzimos a resolução de ORIGEM antes de qualquer
// coisa — e por isso dá pra exportar com qualidade alta sem reabrir o OOM: o
// output cresce de ~300KB para ~1–1.5MB, ainda ~1 ordem de grandeza abaixo do
// pico de decode. Lado maior 2600px + JPEG 0.92 mantém a fonte miúda da NF
// legível pelo OCR (o antigo 2000px/0.85 a apagava e nenhuma IA conseguia ler).

/** Lado maior máximo (px) aprovado para conversões de imagem do OCR de NF. */
export const NF_IMAGE_MAX_DIM = 2600;

/** Qualidade JPEG aprovada para conversões de imagem do OCR de NF. */
export const NF_IMAGE_JPEG_QUALITY = 0.92;

/**
 * Teto de tamanho (bytes) para ler um File direto em base64 SEM recomprimir.
 * Abaixo disso, lemos lossless (a captura já reduziu o arquivo, recomprimir só
 * adiciona artefato de geração que apaga texto). Acima disso, caímos no downscale
 * como salvaguarda de memória — um arquivo grande não deveria chegar aqui.
 */
export const NF_OCR_LOSSLESS_MAX_BYTES = 4 * 1024 * 1024;

/** Remove o prefixo `data:image/...;base64,` retornando só o payload base64. */
export function stripDataUrlPrefix(dataUrl: string): string {
  const commaIdx = dataUrl.indexOf(',');
  return commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl;
}

/**
 * Calcula a escala de downscale mantendo proporção.
 * PORQUÊ: nunca fazer upscale — se a imagem já é menor que maxDim, escala = 1
 * para não inflar memória/peso sem ganho de leitura.
