      file.name,
      NF_RECOVERY_MAX_DIM,
      NF_RECOVERY_JPEG_QUALITY,
    );
    await savePendingCapture(light);
  } catch {
    /* recovery é defesa em profundidade — sem cópia leve, segue o fluxo normal */
  }
}

