165	 * Extrai o primeiro objeto JSON balanceado de um texto.
166	 * Ignora chaves dentro de strings (respeita escapes). Retorna null se não encontrar.
167	 */
168	function extractBalancedJson(text: string): string | null {
169	  if (!text) return null;
170	  let start = -1;
171	  let depth = 0;
172	  let inString = false;
173	  let escape = false;
174	  for (let i = 0; i < text.length; i++) {
175	    const ch = text[i];
176	    if (escape) { escape = false; continue; }
177	    if (ch === '\\') { escape = true; continue; }
178	    if (ch === '"') { inString = !inString; continue; }
179	    if (inString) continue;
180	    if (ch === '{') {
181	      if (depth === 0) start = i;
182	      depth++;
183	    } else if (ch === '}') {
184	      depth--;
185	      if (depth === 0 && start !== -1) {
186	        return text.slice(start, i + 1);
187	      }
188	    }
189	  }
190	  return null;
191	}
