193	function tryParseAiJson(aiResponse: string): any {
194	  if (!aiResponse) return null;
195	  let cleaned = aiResponse.trim();
196	  if (cleaned.startsWith('```json')) {
197	    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```\s*$/, '');
198	  } else if (cleaned.startsWith('```')) {
199	    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```\s*$/, '');
200	  }
201	  const balanced = extractBalancedJson(cleaned) ?? cleaned;
202	  const sanitized = balanced
203	    .replace(/,\s*,/g, ',')
204	    .replace(/,\s*}/g, '}')
205	    .replace(/,\s*]/g, ']');
206	  try {
207	    return JSON.parse(sanitized);
