/**
 * Extrai o primeiro objeto JSON balanceado de um texto.
 * Ignora chaves dentro de strings (respeita escapes). Retorna null se não encontrar.
 */
function extractBalancedJson(text: string): string | null {
  if (!text) return null;
  let start = -1;
  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (escape) { escape = false; continue; }
    if (ch === '\\') { escape = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (ch === '}') {
      depth--;
      if (depth === 0 && start !== -1) {
        return text.slice(start, i + 1);
      }
    }
  }
  return null;
}

function tryParseAiJson(aiResponse: string): any {
  if (!aiResponse) return null;
  let cleaned = aiResponse.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```\s*$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```\s*$/, '');
  }
  const balanced = extractBalancedJson(cleaned) ?? cleaned;
  const sanitized = balanced
    .replace(/,\s*,/g, ',')
    .replace(/,\s*}/g, '}')
    .replace(/,\s*]/g, ']');
  try {
    return JSON.parse(sanitized);
  } catch {
    return null;
  }
}

function hasUsefulContent(parsed: any): boolean {
  if (!parsed || typeof parsed !== 'object') return false;
  const hasNumero = typeof parsed.numero_nota === 'string' && parsed.numero_nota.trim().length > 0;
  const hasFornecedor = typeof parsed.fornecedor === 'string' && parsed.fornecedor.trim().length > 0;
  const hasValor = typeof parsed.valor_total === 'number' && parsed.valor_total > 0;
  const hasItens = Array.isArray(parsed.itens) && parsed.itens.length > 0;
  const hasData = typeof parsed.data_nota === 'string' && parsed.data_nota.trim().length > 0;
  return hasNumero || hasFornecedor || hasValor || hasItens || hasData;
}

async function callOcrModel(
  model: string,
  apiKey: string,
  imageBase64: string,
  prompt: string,
): Promise<{ ok: true; data: any; usage: any; content: string } | { ok: false; reason: string }> {
  try {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'text', text: prompt },
              { type: 'image_url', image_url: { url: `data:image/jpeg;base64,${imageBase64}` } },
            ],
          },
        ],
        temperature: 0.1,
      }),
    });
    if (!response.ok) {
      const errorText = await response.text();
      console.error(`[OCR] ${model} HTTP ${response.status}:`, errorText.slice(0, 300));
      return { ok: false, reason: `http_${response.status}` };
    }
    const data = await response.json();
    const content = data?.choices?.[0]?.message?.content ?? '';
    const parsed = tryParseAiJson(content);
    if (!parsed || typeof parsed !== 'object') {
      console.error(`[OCR] ${model} returned unparseable content:`, content.slice(0, 500));
      return { ok: false, reason: 'unparseable_json' };
    }
    if (!hasUsefulContent(parsed)) {
      console.error(`[OCR] ${model} returned empty object (no useful fields):`, JSON.stringify(parsed).slice(0, 500));
      return { ok: false, reason: 'empty_result' };
    }
    return { ok: true, data: parsed, usage: data.usage, content };
  } catch (e) {
    console.error(`[OCR] ${model} threw:`, (e as Error).message);
    return { ok: false, reason: 'exception' };
  }
}

function normalizeCategoria(raw: unknown): string {
  if (!raw || typeof raw !== 'string') return 'Outros';
  const key = raw.trim().toLowerCase();
  if (!key) return 'Outros';

  const direct = CATEGORIA_ALIASES[key];
  if (direct) return direct;

  for (const canonica of CATEGORIAS_NF) {
    if (key === canonica.toLowerCase()) return canonica;
  }
  for (const [alias, canonica] of Object.entries(CATEGORIA_ALIASES)) {
    if (key.includes(alias)) return canonica;
  }
  return 'Outros';
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      headers: corsHeaders
    });
  }
  const tracer = new EdgeTracer(req, { serviceName: 'gidape-edge-invoice-ocr' });
  const metrics = new EdgeMetrics({ serviceName: 'gidape-edge-invoice-ocr' });
  const rootSpan = tracer.startSpan('process-invoice-ocr');
  rootSpan.setAttribute('operation', 'invoice-ocr');

  try {
    const body = await req.json();
    let imageBase64 = body.imageBase64 || body.image;
    const imageUrl = body.imageUrl as string | undefined;

    // Caminho preferido (foto): o cliente sobe a imagem pro bucket e manda só a
    // URL. Baixamos e fazemos o base64 AQUI no servidor — assim o WebView do
    // Android nunca precisa montar o base64 da foto em alta resolução em
    // memória, que era o gatilho do OOM. O servidor tem memória de sobra e a
    // IA recebe a imagem na resolução cheia. `imageBase64` segue aceito para o
    // caminho de PDF (páginas renderizadas no cliente) e compatibilidade.
    if (!imageBase64 && imageUrl) {
      try {
        const imgResp = await fetch(imageUrl);
        if (!imgResp.ok) {
          throw new Error(`HTTP ${imgResp.status}`);
        }
        const buf = new Uint8Array(await imgResp.arrayBuffer());
        imageBase64 = encodeBase64(buf);
      } catch (e) {
        console.error('[OCR] falha ao baixar imageUrl:', (e as Error).message);
        throw new Error('Não foi possível baixar a imagem para leitura');
      }
    }

    if (!imageBase64) {
      throw new Error('Imagem é obrigatória');
    }

    const openRouterApiKey = Deno.env.get('OPENROUTER_API_KEY');
    if (!openRouterApiKey) {
      console.error('OPENROUTER_API_KEY environment variable not set');
      throw new Error('Configuração da API não encontrada');
    }
    const prompt = `Analise esta nota fiscal ou boleto e extraia as seguintes informações em formato JSON:

{
  "numero_nota": "número da nota fiscal",
