  "cnpj_emitente": "CNPJ do emitente apenas dígitos (14 caracteres), ou null se não houver",
  "endereco_emitente": "endereço completo do emitente em uma string (logradouro, número, bairro, cidade, UF, CEP), ou null se não houver",
  "data_nota": "data de emissão EXATAMENTE como aparece no documento, no formato DD/MM/AAAA",
  "data_vencimento": "data de vencimento EXATAMENTE como aparece no documento, no formato DD/MM/AAAA (NÃO confunda com data de emissão)",
  "valor_total": valor_total_numerico,
  "itens": [
    {
      "nome_produto": "nome do produto",
      "quantidade": quantidade_numerica,
