      "subtotal": subtotal_numerico,
      "categoria": "UMA das 11 categorias permitidas (ver lista abaixo)"
    }
  ]
}

INSTRUÇÕES:
- Extraia TODOS os itens da nota fiscal
- Converta valores para números (sem R$)
- ATENÇÃO: No Brasil, números usam PONTO para separar milhares e VÍRGULA para decimais
- Exemplos de conversão:
  * 322.800,00 (trezentos e vinte e dois mil e oitocentos) → 322800.00
  * 12.000,0000 (doze mil) → 12000.0000
  * 26,90 (vinte e seis reais e noventa centavos) → 26.90
  * 1.500,50 (mil e quinhentos e cinquenta centavos) → 1500.50
- SEMPRE remova pontos de separação de milhares e converta vírgulas para pontos
- Preserve TODAS as casas decimais exatamente como aparecem
- CATEGORIA: escolha EXATAMENTE UMA das 11 opções abaixo, escrita EXATAMENTE como listada (com acentos, capitalização e todos os caracteres idênticos). NÃO invente categorias novas, NÃO use sinônimos, NÃO use plural/singular diferente. Se ficar em dúvida, use "Outros".
  1. "Alimentício" — comida, ingredientes, farinha, açúcar, frutas secas, mercearia, bebidas, pães, quiches, leite, ovos, insumos de produção, folhagens
  2. "Frutas" — somente frutas in natura (morango, banana, abacaxi etc.)
  3. "Embalagens" — caixas, sacolas, copos, potes, guardanapos, filmes, descartáveis, rótulos
  4. "Limpeza" — detergente, álcool, sabão, desinfetante, químicos, higiene, perfumaria, lavanderia, saco de lixo
  5. "Equipamento" — utensílios de cozinha, eletrodomésticos, eletrônicos, EPI, uniforme, vestuário, acessórios, panelas
  6. "Móveis" — mesas, cadeiras, estantes, balcões
  7. "Material de Escritório" — papelaria, canetas, gráfica, toner, impressão, cartões de visita
  8. "Manutenção" — ferramentas, parafusos, madeira, ferragens, peças de reposição, construção, reforma
  9. "Serviços" — frete, logística, transporte, mão de obra, consultoria, serviços terceirizados
  10. "Combustível" — gasolina, diesel, etanol, gás
  11. "Outros" — tudo que não se encaixar nas acima (use por último)
- Se não conseguir identificar algum campo, use null

REGRAS PARA CNPJ E ENDEREÇO DO EMITENTE:
- "cnpj_emitente" deve conter APENAS os 14 dígitos do CNPJ do EMITENTE (quem emitiu a nota / fornecedor), sem pontos, barras ou traços. Ex.: "12345678000199".
- NÃO use o CNPJ do destinatário/tomador (a Momma). Use SEMPRE o emitente.
- "endereco_emitente" deve conter o endereço completo do emitente em UMA string, juntando logradouro, número, bairro, cidade, UF e CEP separados por vírgulas. Ex.: "Rua das Flores, 123, Centro, São Paulo - SP, CEP 01000-000".
- Se algum desses campos não estiver no documento, retorne null.

REGRAS CRÍTICAS PARA DATAS:
- COPIE a data EXATAMENTE como ela aparece impressa no documento
- NÃO converta, NÃO reordene, NÃO interprete a data
- Retorne no formato DD/MM/AAAA (dia/mês/ano) — o formato brasileiro padrão
- Exemplo: se no documento está escrito "03/02/2026", retorne EXATAMENTE "03/02/2026"
- Exemplo: se no documento está escrito "18/02/2026", retorne EXATAMENTE "18/02/2026"
- "data_nota" é a DATA DE EMISSÃO da nota fiscal (campos: "Data de Emissão", "Emissão", "Data NF")
- "data_vencimento" é a DATA DE VENCIMENTO DO BOLETO para pagamento (campos: "Vencimento", "Data de Vencimento", "Vcto", "Venc.")
- NÃO copie a data de emissão para data_vencimento. São campos DIFERENTES.
- Se não existir um boleto ou data de vencimento explícita, retorne data_vencimento como null.
- Certifique-se de que o JSON seja válido, sem vírgulas extras

Responda APENAS com o JSON válido, sem explicações.`;
    const llmStartMs = Date.now();
    let parsedResponse: any = null;
    let usedModel: string | null = null;
    let lastUsage: any = null;
    let lastContent = '';
    const attemptedModels: Array<{ model: string; reason: string }> = [];

    for (const model of OCR_MODEL_CHAIN) {
      const result = await callOcrModel(model, openRouterApiKey, imageBase64, prompt);
      if (result.ok) {
        parsedResponse = result.data;
        usedModel = model;
        lastUsage = result.usage;
        lastContent = result.content;
        break;
      }
      attemptedModels.push({ model, reason: result.reason });
    }

    const llmDurationMs = Date.now() - llmStartMs;

    if (!parsedResponse || !usedModel) {
      console.error('[OCR] All models failed:', attemptedModels);
      rootSpan.setAttribute('success', false);
      rootSpan.setAttribute('ai.fallbacks_exhausted', true);
      rootSpan.endWithError('all_models_failed');
      Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
      return new Response(JSON.stringify({
        error: 'Nenhum modelo de IA conseguiu ler a nota. Tente novamente com uma foto mais nítida.',
        code: 'ocr_models_exhausted',
        attempted_models: attemptedModels,
      }), {
        status: 200,
        headers: {
          ...corsHeaders,
          'Content-Type': 'application/json',
          'traceparent': tracer.getResponseTraceparent(),
        },
      });
    }

    console.log(`[OCR] Sucesso com modelo: ${usedModel} (tentativas: ${attemptedModels.length + 1})`);
    console.log('AI Response:', lastContent);

    // Record AI token metrics
    if (lastUsage) {
      metrics.recordLlmCall({
        model: usedModel,
        provider: 'openrouter',
        operation: 'invoice-ocr',
        inputTokens: lastUsage.prompt_tokens ?? 0,
        outputTokens: lastUsage.completion_tokens ?? 0,
        durationMs: llmDurationMs,
      });
      rootSpan.setAttribute('ai.model', usedModel);
      rootSpan.setAttribute('ai.fallbacks_used', attemptedModels.length);
      rootSpan.setAttribute('ai.input_tokens', lastUsage.prompt_tokens ?? 0);
      rootSpan.setAttribute('ai.output_tokens', lastUsage.completion_tokens ?? 0);
      rootSpan.setAttribute('ai.total_tokens', lastUsage.total_tokens ?? 0);
      rootSpan.setAttribute('ai.duration_ms', llmDurationMs);
    }

    // === SERVER-SIDE DATE CONVERSION ===
    // The AI returns dates exactly as they appear on the document (DD/MM/YYYY).
    // We convert to ISO (YYYY-MM-DD) here in code — deterministic, no AI interpretation.
    console.log('[DATE] Raw data_nota from AI:', parsedResponse.data_nota);
    console.log('[DATE] Raw data_vencimento from AI:', parsedResponse.data_vencimento);
    parsedResponse.data_nota = convertBrazilianDateToISO(parsedResponse.data_nota);
    parsedResponse.data_vencimento = convertBrazilianDateToISO(parsedResponse.data_vencimento);

    // Normaliza CNPJ pra apenas dígitos (modelos às vezes retornam formatado)
    if (typeof parsedResponse.cnpj_emitente === 'string') {
      const onlyDigits = parsedResponse.cnpj_emitente.replace(/\D/g, '');
      parsedResponse.cnpj_emitente = onlyDigits.length === 14 ? onlyDigits : null;
    } else {
      parsedResponse.cnpj_emitente = null;
    }
    if (typeof parsedResponse.endereco_emitente === 'string') {
      parsedResponse.endereco_emitente = parsedResponse.endereco_emitente.trim() || null;
    } else {
      parsedResponse.endereco_emitente = null;
    }
    console.log('[DATE] Converted data_nota:', parsedResponse.data_nota);
    console.log('[DATE] Converted data_vencimento:', parsedResponse.data_vencimento);

    if (Array.isArray(parsedResponse.itens)) {
      parsedResponse.itens = parsedResponse.itens.map((item: any) => {
        const raw = item?.categoria;
        const normalized = normalizeCategoria(raw);
        if (raw && raw !== normalized) {
          console.log(`[CATEGORIA] Normalizada: "${raw}" -> "${normalized}"`);
        }
        return { ...item, categoria: normalized };
      });
    }

    rootSpan.setAttribute('success', true);
    rootSpan.end();

    // Fire-and-forget telemetry flush
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});

    return new Response(JSON.stringify(parsedResponse), {
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
        'traceparent': tracer.getResponseTraceparent(),
      }
    });
  } catch (error) {
    console.error('Error in process-invoice-ocr:', error);

    rootSpan.setAttribute('success', false);
    rootSpan.endWithError(error.message || 'Erro interno do servidor');

    // Fire-and-forget telemetry flush
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});

    return new Response(JSON.stringify({
      error: error.message || 'Erro interno do servidor',
      details: error.toString()
    }), {
      status: 500,
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
        'traceparent': tracer.getResponseTraceparent(),
      }
    });
  }
});

