import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { encodeBase64 } from "https://deno.land/std@0.224.0/encoding/base64.ts";
import "https://deno.land/x/xhr@0.3.0/mod.ts";

// Stubs de telemetria — no-ops (OTEL desabilitado em prod).
// Mantidos localmente para evitar dependência cross-folder no deploy.
class EdgeTracer {
  constructor(_req: Request, _cfg?: any) {}
  startSpan(_name: string) {
    return {
      setAttribute: (_k: string, _v: any) => {},
      end: () => {},
      endWithError: (_m: string) => {},
    };
  }
  getResponseTraceparent() { return ''; }
  async flush() {}
}
class EdgeMetrics {
  constructor(_cfg?: any) {}
  recordLlmCall(_params: any) {}
  async flush() {}
}

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application, traceparent',
  'Access-Control-Allow-Methods': 'POST, OPTIONS'
};

/**
 * Converts a Brazilian date (DD/MM/YYYY) to ISO format (YYYY-MM-DD).
 * Also handles dates the AI may have already converted to YYYY-MM-DD (validates & fixes swaps).
 * Returns null if the date cannot be parsed.
 */
function convertBrazilianDateToISO(dateStr: string | null | undefined): string | null {
  if (!dateStr || dateStr === 'null') return null;
  const cleaned = dateStr.trim();

  // Case 1: DD/MM/YYYY or DD-MM-YYYY (Brazilian format — most reliable)
  const brMatch = cleaned.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
  if (brMatch) {
    const day = brMatch[1].padStart(2, '0');
    const month = brMatch[2].padStart(2, '0');
    const year = brMatch[3];
    const m = parseInt(month);
    const d = parseInt(day);
    if (m >= 1 && m <= 12 && d >= 1 && d <= 31) {
      return `${year}-${month}-${day}`;
    }
    if (m > 12 && d >= 1 && d <= 12) {
      return `${year}-${day.padStart(2, '0')}-${month}`;
    }
    return `${year}-${month}-${day}`;
  }

  // Case 2: YYYY-MM-DD (AI already converted — validate and fix if swapped)
  const isoMatch = cleaned.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (isoMatch) {
    const year = isoMatch[1];
    const part1 = isoMatch[2];
    const part2 = isoMatch[3];
    const p1 = parseInt(part1);
    const p2 = parseInt(part2);
    if (p1 > 12 && p2 >= 1 && p2 <= 12) {
      console.log(`[DATE FIX] Swapped date detected: ${cleaned} → ${year}-${part2}-${part1}`);
      return `${year}-${part2}-${part1}`;
    }
    return cleaned;
  }

  console.warn(`[DATE WARN] Could not parse date: ${dateStr}`);
  return cleaned;
}

const CATEGORIAS_NF = [
  'Alimentício',
  'Frutas',
  'Embalagens',
  'Limpeza',
